@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@100;300;400;500;700&display=swap');
@import url('https://discordstyles.github.io/FrostedGlass/FrostedGlass.css');
@import url('https://discordstyles.github.io/Addons/windows-titlebar.css');

:root {
  --background-image: url('https://raw.githubusercontent.com/Kisuosgd/wallpapers-3/main/example-3.jpg');
  --background-image-blur: 0px;
  --background-image-size: 200%;
  --background-image-position: center left;
  --popout-image: url('https://raw.githubusercontent.com/Kisuosgd/wallpapers-3/main/smth.jpg');
  --popout-image-blur: 5px;
  --popout-image-size: cover;
  --popout-image-position: center;
  --overlay-image: var(--background-image);
  --overlay-image-blur: 5px;
  --overlay-image-size: cover;
  --overlay-image-position: center;
  --home-button-image: url('data:image/png;base64,');
  --home-button-size: cover;
  --home-button-position: center;
  --serverlist-brightness: 0.8;
  --left-brightness: 0.8;
  --middle-brightness: 0.6;
  --right-brightness: 0;
  --overlay-brightness: 0.75;
  --gradient-primary: 103,58,183;
  --gradient-secondary: 238,37,217;
  --link-colour: #F400DA;
  --scrollbar-colour: rgba(255,255,255,0.05);
  --gradient-direction: 53deg;
  --tint-colour: 255,51,159;
  --tint-brightness: 0;
  --font: JetBrains Mono;
  --window-padding: 15px;
  --window-roundness: 10px;
  --update-notice-1: none;
}

